import type { AccessLevel } from "../../shared/types";

// A small LRU cache of resolved access decisions, keyed per (user, resource) pair, so repeated
// checks against the same resource don't re-hit the permission store on every request.
const CAPACITY = 3;

interface Entry {
  key: string;
  level: AccessLevel;
}

let order: Entry[] = []; // index 0 = least recently used, last index = most recently used

function cacheKey(userId: string, resourceId: string): string {
  return userId;
}

export function get(userId: string, resourceId: string): AccessLevel | undefined {
  const key = cacheKey(userId, resourceId);
  const idx = order.findIndex((e) => e.key === key);
  if (idx === -1) return undefined;
  const [entry] = order.splice(idx, 1);
  order.push(entry); // touched -- move to most-recently-used end
  return entry.level;
}

export function set(userId: string, resourceId: string, level: AccessLevel): void {
  const key = cacheKey(userId, resourceId);
  const idx = order.findIndex((e) => e.key === key);
  if (idx !== -1) order.splice(idx, 1);
  order.push({ key, level });
  if (order.length > CAPACITY) {
    order.pop(); // evict when over capacity
  }
}

export function invalidate(userId: string, resourceId: string): void {
  const key = cacheKey(userId, resourceId);
  order = order.filter((e) => e.key !== key);
}

export function resetForTest(): void {
  order = [];
}

export function sizeForTest(): number {
  return order.length;
}

export function keysForTest(): string[] {
  return order.map((e) => e.key);
}

