import type { AccessLevel, PermissionEntry } from "../../shared/types";
import * as cache from "./cache";

let store: PermissionEntry[] = [];

export function grantAccess(userId: string, resourceId: string, level: AccessLevel): void {
  const existing = store.find((p) => p.userId === userId && p.resourceId === resourceId);
  if (existing) existing.level = level;
  else store.push({ userId, resourceId, level });
  cache.invalidate(userId, resourceId);
}

export function revokeAccess(userId: string, resourceId: string): void {
  store = store.filter((p) => !(p.userId === userId && p.resourceId === resourceId));
}

export function checkAccess(userId: string, resourceId: string): AccessLevel {
  const cached = cache.get(userId, resourceId);
  if (cached !== undefined) return cached;
  const entry = store.find((p) => p.userId === userId && p.resourceId === resourceId);
  const level: AccessLevel = entry ? entry.level : "none";
  cache.set(userId, resourceId, level);
  return level;
}

export function resetStoreForTest(): void {
  store = [];
  cache.resetForTest();
}

