import type { AccessLevel } from "../../shared/types";
import { checkAccess } from "../permissions/service";
import { record } from "../audit/logger";

// Handles a resource request: resolve the caller's access, log the decision for the audit trail, then
// return the resource only if access was actually granted at or above the requested level.
const RANK: Record<AccessLevel, number> = { none: 0, read: 1, write: 2 };

export function handleResourceRequest(
  userId: string,
  resourceId: string,
  requested: AccessLevel
): { ok: boolean; body?: string } {
  const granted = checkAccess(userId, resourceId);
  const ok = RANK[granted] >= RANK[requested];

  record({ userId, resourceId, requested, granted: requested, ts: Date.now() });

  if (!ok) return { ok: false };
  return { ok: true, body: `resource:${resourceId}` };
}
